public static UnitOfMeasureInternalCode avaFindByCodeSymbol(UnitOfMeasureCodeSymbol _unitOfMeasureCodeSymbol, boolean _forUpdate = false)
{
    UnitOfMeasureInternalCode   unitOfMeasureInternalCode;

    unitOfMeasureInternalCode.selectForUpdate(_forUpdate);

    select firstonly unitOfMeasureInternalCode
        where unitOfMeasureInternalCode.CodeSymbol == _unitOfMeasureCodeSymbol;

    return unitOfMeasureInternalCode;
}

public static UnitOfMeasureSymbol avaCodeSymbol2Symbol(UnitOfMeasureCodeSymbol _unitOfMeasureCodeSymbol)
{
    UnitOfMeasureSymbol         unitOfMeasureSymbol;
    UnitOfMeasure               unitOfMeasure;
    UnitOfMeasureInternalCode   unitOfMeasureInternalCode;

    select firstonly Symbol, RecId from unitOfMeasure
        exists join unitOfMeasureInternalCode
        where unitOfMeasureInternalCode.UnitOfMeasure   == unitOfMeasure.RecId
           && unitOfMeasureInternalCode.CodeSymbol      == _unitOfMeasureCodeSymbol;

    if (unitOfMeasure)
    {
        unitOfMeasureSymbol = unitOfMeasure.Symbol;
    }

    return unitOfMeasureSymbol;
}
